import{B as e,C as t,et as n,g as ee,rt as r,tt as te,x as i,z as ne}from"./Dia7F_pD.js";import"./xihTtKlq.js";import"./B_Tv1BKG.js";var a=r({default:()=>de,metadata:()=>o}),o={title:`Architecture Overview`,description:`How Wihaister's tunnel system works under the hood.`,section:`Architecture`,order:10,published:!0,updated:`2026-08-16T00:00:00.000Z`,toc:[`The Wihaister Tunnel`,`Connection Flow`,`Security Model`,`Protocol Components`,`Resilience`]},{title:re,description:ie,section:ae,order:oe,published:se,updated:ce,toc:le}=o,ue=t(`<h2 id="the-wihaister-tunnel">The Wihaister Tunnel</h2> <p>Wihaister uses <strong>QUIC</strong> as its transport protocol, providing a secure, multiplexed connection between two endpoints. A single encrypted tunnel carries every part of your session.</p> <pre class="language-undefined"></pre> <h2 id="connection-flow">Connection Flow</h2> <ol><li><strong>Handshake</strong>: The client initiates a QUIC connection to the server.</li> <li><strong>NAT Traversal</strong>: Wihaister attempts direct peer-to-peer connection using hole-punching techniques.</li> <li><strong>Relay Fallback</strong>: If direct connection fails, traffic routes through an encrypted relay. The relay forwards encrypted bytes without decryption capability.</li> <li><strong>Session Establishment</strong>: Once connected, the tunnel multiplexes remote desktop, terminal, file, camera, and HID streams.</li></ol> <h2 id="security-model">Security Model</h2> <ul><li>All traffic is <strong>end-to-end encrypted</strong> using TLS 1.3 over QUIC.</li> <li>Encryption keys are generated per session and never shared with relay infrastructure.</li> <li>No plaintext traffic is ever transmitted.</li> <li>Relay servers only see encrypted bytes — not even we can read your traffic.</li></ul> <h2 id="protocol-components">Protocol Components</h2> <p>The tunnel carries multiple multiplexed streams:</p> <table><thead><tr><th>Stream Type</th><th>Purpose</th></tr></thead><tbody><tr><td>Remote Desktop</td><td>Screen capture and streaming</td></tr><tr><td>Terminal</td><td>PTY sessions</td></tr><tr><td>File Transfer</td><td>Remote file browsing, previews, and downloads</td></tr><tr><td>Camera</td><td>Forwarding of workstation cameras</td></tr><tr><td>HID Forwarding</td><td>Keyboard, mouse, and touch input</td></tr></tbody></table> <h2 id="resilience">Resilience</h2> <p>Wihaister watches the health of your connection during a session:</p> <ul><li><strong>Reconnection</strong>: if the tunnel drops, the client reconnects automatically.</li> <li><strong>Adaptive quality</strong>: stream quality adjusts to available bandwidth, so a busy network slows the picture rather than breaking it.</li> <li><strong>Relay fallback</strong>: sessions that cannot establish a direct path stay connected through the encrypted relay for as long as needed.</li></ul>`,1);function de(t){var r=ue(),a=e(ne(r),4);ee(a,()=>`<code class="language-undefined">Your device                              Workstation
    │                                         │
    │   QUIC connection (TLS 1.3)             │
    │◄───────────────────────────────────────►│
    │   Remote desktop  ────────────────────► │
    │   Terminal        ◄───────────────────► │
    │   File browser    ◄───────────────────► │
    │   Camera          ◄───────────────────► │
    │   HID input       ────────────────────► │</code>`,!0),te(a),n(20),i(t,r)}var fe=r({default:()=>be,metadata:()=>s}),s={title:`Camera Streaming`,description:`Use a camera attached to your workstation from your client device.`,section:`Basics`,order:40,published:!0,updated:`2026-08-16T00:00:00.000Z`,toc:[`What Camera Streaming Does`,`Starting a Camera Stream`,`Permissions`,`Quality and Performance`,`Privacy`]},{title:pe,description:me,section:he,order:ge,published:_e,updated:ve,toc:ye}=s,c=t(`<h2 id="what-camera-streaming-does">What Camera Streaming Does</h2> <p>Camera streaming forwards a camera attached to your workstation — for example a webcam or a capture device — to your client device. The camera image is captured on the workstation, compressed, and delivered over your encrypted tunnel.</p> <p>This is useful for checking a physical space, monitoring a workbench, or using a workstation camera that your client device does not have access to.</p> <h2 id="starting-a-camera-stream">Starting a Camera Stream</h2> <ol><li>Connect to the workstation as usual.</li> <li>Open the camera view in the client.</li> <li>Select the camera you want to use on the workstation.</li></ol> <p>The stream starts automatically. Close the camera view to stop the stream.</p> <h2 id="permissions">Permissions</h2> <p>On macOS, Wihaister needs camera access on the <strong>workstation</strong>:</p> <ol><li>Open <strong>System Settings → Privacy & Security → Camera</strong>.</li> <li>Enable Wihaister.</li> <li>Restart the Wihaister service if the camera does not appear.</li></ol> <p>On Windows, the camera is available when the tunnel service is running in the system tray.</p> <h2 id="quality-and-performance">Quality and Performance</h2> <p>Camera frames are compressed on the workstation before being sent, so the stream adapts to your connection. If the image quality drops, it usually means your connection is congested — the stream will recover automatically as bandwidth becomes available.</p> <h2 id="privacy">Privacy</h2> <p>Camera frames travel through the same end-to-end encrypted QUIC tunnel as everything else in your session. Frames are never transmitted in plaintext, and a relay server used for fallback routing can only forward encrypted bytes — it cannot see your camera feed.</p>`,1);function be(e){var t=c();n(26),i(e,t)}var xe=r({default:()=>d,metadata:()=>l}),l={title:`Feature Availability`,description:`Which platforms and features are available today, in development, or planned.`,section:`Basics`,order:60,published:!0,updated:`2026-08-16T00:00:00.000Z`,toc:[`Platforms`,`Features`,`How to Read This Page`]},{title:Se,description:Ce,section:we,order:Te,published:Ee,updated:De,toc:Oe}=l,u=t(`<h2 id="platforms">Platforms</h2> <table><thead><tr><th>Platform</th><th>Status</th></tr></thead><tbody><tr><td>Windows</td><td>Available today</td></tr><tr><td>macOS</td><td>Available today</td></tr><tr><td>Linux</td><td>Planned</td></tr><tr><td>iOS</td><td>In active development</td></tr><tr><td>Android</td><td>In active development</td></tr></tbody></table> <p>You can connect to a workstation from any device running a supported client. Platforms marked “in development” are not yet distributed with the early access builds.</p> <h2 id="features">Features</h2> <table><thead><tr><th>Feature</th><th>Status</th></tr></thead><tbody><tr><td>Remote desktop (4K / 60 FPS)</td><td>Available</td></tr><tr><td>Keyboard and mouse forwarding</td><td>Available</td></tr><tr><td>Touch input mapping</td><td>Available</td></tr><tr><td>Terminal sessions</td><td>Available</td></tr><tr><td>File browsing and downloads</td><td>Available</td></tr><tr><td>Camera streaming</td><td>Available</td></tr><tr><td>Screen sharing with teammates</td><td>Planned</td></tr><tr><td>View-only and full-control permission modes</td><td>Planned</td></tr></tbody></table> <h2 id="how-to-read-this-page">How to Read This Page</h2> <p>“Available” means the feature ships in the current early access builds for at least one platform; the <a href="/docs/basics/permissions">Permissions</a> page lists what each feature needs on the workstation. Features marked “Planned” are on the roadmap but are not part of the current builds — do not expect them to work yet.</p> <p>This page is updated as the early access programme progresses. The list of supported platforms and features is also mirrored on the <a href="/docs/basics/getting-started">Getting Started</a> page.</p>`,1);function d(e){var t=u();n(14),i(e,t)}var f=r({default:()=>h,metadata:()=>p}),p={title:`File Transfer`,description:`Browse files on your workstation, preview them, and download them to your device.`,section:`Basics`,order:30,published:!0,updated:`2026-08-16T00:00:00.000Z`,toc:[`Browsing Remote Files`,`Previewing Files`,`Downloading Files`,`Managing Files`,`Transfer Security`]},{title:ke,description:Ae,section:je,order:Me,published:Ne,updated:Pe,toc:Fe}=p,m=t(`<h2 id="browsing-remote-files">Browsing Remote Files</h2> <p>The Files view gives you a window into the file system of the connected workstation. You can:</p> <ul><li>Navigate folders with breadcrumbs, just like a local file manager</li> <li>Jump to common locations (Home, Desktop, Downloads) from the bookmarks menu</li> <li>Switch between list and grid views</li> <li>Sort entries by name, kind, size, or modification date</li></ul> <p>Folder listings are sent as lightweight metadata, so opening a folder feels instant even on slower connections. Thumbnails for images and other supported files load progressively in the background.</p> <h2 id="previewing-files">Previewing Files</h2> <p>Select a file and choose <strong>Preview</strong> to see its contents without downloading it first. Previews are generated on the workstation and sent over the tunnel, so large files never need to travel to your device just so you can peek at them.</p> <h2 id="downloading-files">Downloading Files</h2> <p>To copy a file to your device:</p> <ol><li>Open the folder containing the file.</li> <li>Select the file (or use multi-select for several files at once).</li> <li>Choose <strong>Download</strong> from the context menu.</li> <li>Pick a destination on your device.</li></ol> <p>Downloads travel over the same end-to-end encrypted QUIC tunnel as the rest of your session.</p> <h2 id="managing-files">Managing Files</h2> <p>The Files view also supports basic file management on the workstation:</p> <ul><li><strong>Rename</strong> — rename files and folders in place</li> <li><strong>Delete</strong> — remove entries, with a confirmation step before anything is deleted</li> <li><strong>New folder</strong> — create directories on the workstation</li> <li><strong>Get Info</strong> — see size, modification date, permissions, and other details</li></ul> <h2 id="transfer-security">Transfer Security</h2> <p>File listings, previews, and downloads are all carried inside your encrypted tunnel. Nothing related to your files ever travels in plaintext, and relay servers used for fallback routing only forward encrypted bytes — they cannot read your data.</p>`,1);function h(e){var t=m();n(28),i(e,t)}var g=r({default:()=>y,metadata:()=>_}),_={title:`Getting Started`,description:`Set up Wihaister and make your first connection.`,section:`Basics`,order:10,published:!0,updated:`2026-08-16T00:00:00.000Z`,toc:[`Early Access`,`Installing Wihaister`,`Making Your First Connection`,`Platform Availability`,`System Requirements`]},{title:Ie,description:Le,section:Re,order:ze,published:Be,updated:Ve,toc:He}=_,v=t(`<h2 id="early-access">Early Access</h2> <p>Wihaister is currently available through the early access programme. Installers are sent out to early access members — if you have not received one yet, <a href="/">get early access</a>.</p> <h2 id="installing-wihaister">Installing Wihaister</h2> <h3 id="windows">Windows</h3> <ol><li>Run the <code>.exe</code> installer and follow the setup wizard.</li> <li>Wihaister starts automatically after installation.</li> <li>A system tray icon appears when the tunnel service is running.</li></ol> <h3 id="macos">macOS</h3> <ol><li>Open the <code>.dmg</code> disk image and drag Wihaister to your Applications folder.</li> <li>Launch Wihaister from Applications.</li> <li>Grant screen recording permissions when prompted (required for remote desktop).</li></ol> <h2 id="making-your-first-connection">Making Your First Connection</h2> <p>Once installed, you can connect to any machine running Wihaister:</p> <ol><li>Open the Wihaister client on both machines.</li> <li>Share a connection code from the host machine.</li> <li>Enter the code on the client machine.</li> <li>The connection establishes automatically.</li></ol> <h2 id="platform-availability">Platform Availability</h2> <ul><li><strong>Windows</strong> and <strong>macOS</strong> are available today.</li> <li><strong>Linux</strong> support is planned.</li> <li><strong>iOS</strong> and <strong>Android</strong> clients are in active development.</li></ul> <h2 id="system-requirements">System Requirements</h2> <ul><li><strong>Windows</strong>: Windows 10 or later</li> <li><strong>macOS</strong>: macOS 12 Monterey or later</li></ul>`,1);function y(e){var t=v();n(26),i(e,t)}var b=r({default:()=>C,metadata:()=>x}),x={title:`Permissions`,description:`Which permissions Wihaister needs on the workstation, and how to grant them.`,section:`Basics`,order:45,published:!0,updated:`2026-08-16T00:00:00.000Z`,toc:[`macOS`,`Windows`,`Granting macOS Permissions`,`Frequently Asked Questions`]},{title:Ue,description:We,section:Ge,order:Ke,published:qe,updated:Je,toc:Ye}=x,S=t(`<h2 id="macos">macOS</h2> <p>When Wihaister runs as the host on macOS, it may ask for these permissions:</p> <table><thead><tr><th>Permission</th><th>Why it is needed</th><th>What breaks without it</th></tr></thead><tbody><tr><td>Screen Recording</td><td>Capturing the screen to stream the remote desktop</td><td>Remote desktop shows a black screen</td></tr><tr><td>Camera</td><td>Streaming cameras attached to the workstation</td><td>The camera feed is unavailable</td></tr><tr><td>Accessibility</td><td>Forwarding keyboard and mouse input</td><td>Input is not delivered to applications</td></tr></tbody></table> <p>You are only prompted for permissions the first time the corresponding feature is used.</p> <h2 id="windows">Windows</h2> <p>On Windows, Wihaister runs as a service with a tray icon. Streaming and input forwarding do not require special permissions. If the tunnel service is not running, the tray icon is missing — start Wihaister from the Start menu.</p> <h2 id="granting-macos-permissions">Granting macOS Permissions</h2> <p>Permissions can be granted or revoked at any time:</p> <ol><li>Open <strong>System Settings → Privacy & Security</strong>.</li> <li>Select the permission category (<strong>Screen Recording</strong>, <strong>Camera</strong>, or <strong>Accessibility</strong>).</li> <li>Enable Wihaister.</li> <li>Restart the Wihaister service so the change takes effect.</li></ol> <p>macOS may ask you to restart an app after changing its Screen Recording permission.</p> <h2 id="frequently-asked-questions">Frequently Asked Questions</h2> <p><strong>I granted Screen Recording but the screen is still black.</strong> Restart the Wihaister service — macOS only applies the change after the app restarts.</p> <p><strong>A permission is missing from the list.</strong> Run Wihaister once — the app only appears in a category after it has requested that permission. If it is still missing, reinstall the app.</p> <p><strong>Do permissions affect privacy?</strong> Permissions are checked by the operating system on the workstation only. Everything captured is streamed through your end-to-end encrypted tunnel; nothing is stored by Wihaister.</p>`,1);function C(e){var t=S();n(26),i(e,t)}var w=r({default:()=>D,metadata:()=>T}),T={title:`Remote Desktop Controls`,description:`Everything you can do once you are looking at the remote screen.`,section:`Basics`,order:20,published:!0,updated:`2026-08-16T00:00:00.000Z`,toc:[`Choosing a Monitor`,`Picture Quality`,`Keyboard and Mouse`,`Touch Controls`,`Ending a Session`]},{title:Xe,description:Ze,section:Qe,order:$e,published:et,updated:tt,toc:nt}=T,E=t(`<h2 id="choosing-a-monitor">Choosing a Monitor</h2> <p>When you connect, Wihaister streams a monitor from the workstation. If the workstation has several displays, you can switch between them from the client — one monitor at a time. The list of available monitors is fetched when the session starts, and picking a different monitor switches the stream without reconnecting.</p> <h2 id="picture-quality">Picture Quality</h2> <p>Wihaister supports streaming up to <strong>4K at 60 FPS</strong>. The stream adapts to your connection automatically: on a fast network the picture stays at full quality, and on a congested one the quality steps down gracefully instead of freezing or dropping the session. As bandwidth recovers, quality steps back up on its own.</p> <h2 id="keyboard-and-mouse">Keyboard and Mouse</h2> <p>Your keyboard and mouse are forwarded to the workstation in real time:</p> <ul><li>Typing, shortcuts, and modifier keys behave as if you were sitting at the machine</li> <li>Clicks, drags, and scrolling are forwarded as mouse input</li> <li>The client translates your gestures into the events the workstation expects</li></ul> <p>No configuration is required — input forwarding is active as soon as the session starts.</p> <h2 id="touch-controls">Touch Controls</h2> <p>On touch-capable devices you can control the session with touch. Taps and gestures are mapped onto mouse actions on the workstation. See <a href="/docs/basics/touch-input">Touch Input</a> for details.</p> <h2 id="ending-a-session">Ending a Session</h2> <p>Close the remote desktop view or disconnect from the client to end the session. The tunnel tears down automatically.</p>`,1);function D(e){var t=E();n(22),i(e,t)}var O=r({default:()=>j,metadata:()=>k}),k={title:`Terminal Sessions`,description:`Open an interactive shell on the remote workstation.`,section:`Basics`,order:25,published:!0,updated:`2026-08-16T00:00:00.000Z`,toc:[`What a Terminal Session Is`,`Opening a Session`,`Working with Sessions`,`Security`]},{title:rt,description:it,section:at,order:ot,published:st,updated:ct,toc:lt}=k,A=t(`<h2 id="what-a-terminal-session-is">What a Terminal Session Is</h2> <p>A terminal session gives you an interactive shell on the remote workstation — the same kind of prompt you would get by opening a terminal on the machine itself. Your usual shell and command-line tools are available, so you can run builds, manage processes, edit config files, and troubleshoot without leaving the Wihaister client.</p> <p>Each session runs as a separate shell process on the workstation, inside the same end-to-end encrypted tunnel as the rest of your session.</p> <h2 id="opening-a-session">Opening a Session</h2> <ol><li>Connect to the workstation.</li> <li>Open the terminal view in the client.</li> <li>A shell starts on the workstation and appears in the client.</li></ol> <p>On the workstation side no additional setup is needed — sessions are created on demand over the tunnel.</p> <h2 id="working-with-sessions">Working with Sessions</h2> <ul><li>You can open <strong>multiple sessions</strong> and switch between them; each keeps its own working directory and process list</li> <li>Sessions are independent — a long-running command in one session does not block the others</li> <li>Keyboard input, scrolling, and selection behave like a local terminal</li></ul> <h2 id="security">Security</h2> <p>Everything you type and every byte of output travels through your encrypted tunnel. Terminal traffic is never sent in plaintext, and relay servers used for fallback routing can only forward encrypted bytes.</p>`,1);function j(e){var t=A();n(18),i(e,t)}var M=r({default:()=>_t,metadata:()=>N}),N={title:`Touch Input`,description:`Control your workstation with touch gestures on touch-capable devices.`,section:`Basics`,order:40,published:!0,updated:`2026-08-16T00:00:00.000Z`,toc:[`How Touch Mapping Works`,`Common Gestures`,`Combining Touch and Keyboard`]},{title:ut,description:dt,section:ft,order:pt,published:mt,updated:ht,toc:gt}=N,P=t(`<h2 id="how-touch-mapping-works">How Touch Mapping Works</h2> <p>Wihaister maps touch gestures from your client device onto mouse actions on the workstation. This lets you drive the remote desktop naturally from a touchscreen — for example from a tablet or a touch laptop.</p> <p>Touch input travels through the same encrypted tunnel as keyboard and mouse input, and is active whenever the remote desktop session is running.</p> <h2 id="common-gestures">Common Gestures</h2> <ul><li><strong>Tap</strong> — a mouse click at the tapped position</li> <li><strong>Drag</strong> — press-and-move, forwarded as a mouse drag (used for selecting text, moving windows, and drawing)</li> <li><strong>Scroll</strong> — swiping with a scrolling gesture sends scroll events</li></ul> <p>The exact gesture set available depends on your client. Touch interaction is designed to work together with the on-screen keyboard of your device.</p> <h2 id="combining-touch-and-keyboard">Combining Touch and Keyboard</h2> <p>When your device shows an on-screen keyboard, its keystrokes are forwarded to the workstation just like physical keyboard input. You can type into text fields and terminals using touch for navigation and the on-screen keyboard for text.</p>`,1);function _t(e){var t=P();n(14),i(e,t)}var vt=r({default:()=>Dt,metadata:()=>F}),F={title:`Troubleshooting`,description:`Fix common connection, permission, and performance issues.`,section:`Basics`,order:50,published:!0,updated:`2026-08-16T00:00:00.000Z`,toc:[`The Screen Is Black`,`The Camera Feed Is Missing`,`Connection Code Problems`,`Connection Is Slow`,`Why Is My Session Using a Relay`,`Connection Drops`,`Collecting Diagnostics`,`Still Stuck`]},{title:yt,description:bt,section:xt,order:St,published:Ct,updated:wt,toc:Tt}=F,Et=t(`<h2 id="the-screen-is-black">The Screen Is Black</h2> <p>A black remote desktop almost always means a missing permission on the host (the machine being controlled). See <a href="/docs/basics/permissions">Permissions</a> for the full list.</p> <p>Quick checklist:</p> <ul><li><strong>macOS</strong>: grant Screen Recording permission and restart the Wihaister service</li> <li><strong>Windows</strong>: confirm the tunnel service is running — its icon should be visible in the system tray</li> <li>Both machines online and connected to the same Wihaister network</li></ul> <h2 id="the-camera-feed-is-missing">The Camera Feed Is Missing</h2> <p>Camera streaming requires camera access on the <strong>workstation</strong>:</p> <ol><li>Open <strong>System Settings → Privacy & Security → Camera</strong> (macOS).</li> <li>Enable Wihaister and restart the service.</li></ol> <p>Also make sure another application is not already using the camera exclusively — most cameras can only be opened by one application at a time.</p> <h2 id="connection-code-problems">Connection Code Problems</h2> <p>Connection codes are <strong>single-use</strong> and valid for <strong>48 hours</strong> from the moment they are generated.</p> <ul><li>If a code is rejected, generate a new one on the host and try again — the old code cannot be reused</li> <li>Enter the code exactly as shown, including the dashes (format: <code>XXXX-XXXX-XXXX</code>)</li> <li>Codes expire automatically after 48 hours even if they were never used</li></ul> <h2 id="connection-is-slow">Connection Is Slow</h2> <p>Wihaister adjusts stream quality to match your network conditions automatically. If the picture feels sluggish:</p> <ul><li>Move closer to your Wi-Fi access point or use a wired connection</li> <li>Close bandwidth-heavy applications on both machines</li> <li>Keep in mind that both endpoints matter: the slowest hop in the path limits the whole session</li> <li>Sessions that run through the relay fallback have higher latency than direct connections</li></ul> <h2 id="why-is-my-session-using-a-relay">Why Is My Session Using a Relay</h2> <p>Wihaister always tries to establish a <strong>direct peer-to-peer connection</strong> between your devices, punching through NATs and firewalls automatically. In some network environments a direct path simply cannot be established — restrictive firewalls or carrier-grade NAT are common causes.</p> <p>When that happens, the session falls back to a relay server for as long as needed. Your traffic is still <strong>end-to-end encrypted</strong>: the relay only forwards encrypted bytes and cannot read your data. Functionally, relayed sessions behave the same as direct ones; they may have slightly higher latency.</p> <p>There is no way to see from inside the product whether a session is direct or relayed — the connection behaves identically either way.</p> <h2 id="connection-drops">Connection Drops</h2> <ul><li>Confirm both machines are online and Wihaister is running on both</li> <li>The client reconnects automatically — wait a moment before retrying manually</li> <li>Re-enter the connection code if the session cannot be resumed; codes are single-use, so share a fresh one from the host</li> <li>If the tunnel service appears unresponsive, restart it on the host and reconnect</li></ul> <h2 id="collecting-diagnostics">Collecting Diagnostics</h2> <p>If you need help from the team, gathering a few details first speeds things up:</p> <ul><li>Which platforms both machines run (and their OS versions)</li> <li>What you were doing when the problem appeared</li> <li>Whether the problem happens on every connection or only specific networks</li> <li>The exact wording of any error message</li></ul> <p>For advanced diagnostics, the desktop client can be started with verbose logging by setting the <code>RUST_LOG</code> environment variable to <code>debug</code> before launching it from a terminal.</p> <h2 id="still-stuck">Still Stuck</h2> <p>Wihaister is in early access. If you cannot resolve an issue with the steps above, reach out through the channel in your early access invitation — including the diagnostics from the section above.</p>`,1);function Dt(e){var t=Et();n(50),i(e,t)}var Ot=r({default:()=>Lt,metadata:()=>I}),I={title:`Kamera-Streaming`,description:`Nutzen Sie eine Kamera an Ihrer Workstation von Ihrem Client-Gerät aus.`,section:`Basics`,order:35,published:!0,updated:`2026-08-16T00:00:00.000Z`,toc:[`Was Kamera-Streaming macht`,`Einen Kamerastream starten`,`Berechtigungen`,`Qualität und Leistung`,`Privatsphäre`]},{title:kt,description:At,section:jt,order:Mt,published:Nt,updated:Pt,toc:Ft}=I,It=t(`<h2 id="was-kamera-streaming-macht">Was Kamera-Streaming macht</h2> <p>Kamera-Streaming leitet eine Kamera, die mit Ihrer Workstation verbunden ist — zum Beispiel eine Webcam oder ein Aufnahmegerät — an Ihr Client-Gerät weiter. Das Kamerabild wird auf der Workstation erfasst, komprimiert und über Ihren verschlüsselten Tunnel übertragen.</p> <p>Das ist praktisch, um einen physischen Ort im Blick zu behalten, eine Werkbank zu überwachen oder eine Workstation-Kamera zu nutzen, zu der Ihr Client-Gerät keinen Zugang hat.</p> <h2 id="einen-kamerastream-starten">Einen Kamerastream starten</h2> <ol><li>Verbinden Sie sich wie gewohnt mit der Workstation.</li> <li>Öffnen Sie die Kameraansicht im Client.</li> <li>Wählen Sie die Kamera aus, die Sie auf der Workstation nutzen möchten.</li></ol> <p>Der Stream startet automatisch. Schließen Sie die Kameraansicht, um den Stream zu beenden.</p> <h2 id="berechtigungen">Berechtigungen</h2> <p>Auf macOS benötigt Wihaister Kamerazugriff auf der <strong>Workstation</strong>:</p> <ol><li>Öffnen Sie <strong>Systemeinstellungen → Datenschutz & Sicherheit → Kamera</strong>.</li> <li>Aktivieren Sie Wihaister.</li> <li>Starten Sie den Wihaister-Dienst neu, falls die Kamera nicht erscheint.</li></ol> <p>Unter Windows ist die Kamera verfügbar, wenn der Tunnel-Dienst im System-Tray läuft.</p> <h2 id="qualität-und-leistung">Qualität und Leistung</h2> <p>Kameraframes werden auf der Workstation komprimiert, bevor sie gesendet werden, sodass sich der Stream an Ihre Verbindung anpasst. Sinkt die Bildqualität, ist Ihre Verbindung in der Regel ausgelastet — der Stream erholt sich automatisch, sobald wieder Bandbreite verfügbar ist.</p> <h2 id="privatsphäre">Privatsphäre</h2> <p>Kameraframes laufen durch denselben Ende-zu-Ende-verschlüsselten QUIC-Tunnel wie alles andere in Ihrer Sitzung. Frames werden niemals im Klartext übertragen, und ein Relay-Server, der für das Fallback-Routing genutzt wird, kann nur verschlüsselte Bytes weiterleiten — Ihr Kamerabild ist für ihn nicht sichtbar.</p>`,1);function Lt(e){var t=It();n(26),i(e,t)}var Rt=r({default:()=>qt,metadata:()=>L}),L={title:`Funktionsverfügbarkeit`,description:`Welche Plattformen und Funktionen heute verfügbar, in Entwicklung oder geplant sind.`,section:`Basics`,order:60,published:!0,updated:`2026-08-16T00:00:00.000Z`,toc:[`Plattformen`,`Funktionen`,`So lesen Sie diese Seite`]},{title:zt,description:Bt,section:Vt,order:Ht,published:Ut,updated:Wt,toc:Gt}=L,Kt=t(`<h2 id="plattformen">Plattformen</h2> <table><thead><tr><th>Plattform</th><th>Status</th></tr></thead><tbody><tr><td>Windows</td><td>Heute verfügbar</td></tr><tr><td>macOS</td><td>Heute verfügbar</td></tr><tr><td>Linux</td><td>Geplant</td></tr><tr><td>iOS</td><td>In aktiver Entwicklung</td></tr><tr><td>Android</td><td>In aktiver Entwicklung</td></tr></tbody></table> <p>Sie können sich von jedem Gerät mit einem unterstützten Client mit einer Workstation verbinden. Als „in Entwicklung” markierte Plattformen werden mit den Early-Access-Builds noch nicht verteilt.</p> <h2 id="funktionen">Funktionen</h2> <table><thead><tr><th>Funktion</th><th>Status</th></tr></thead><tbody><tr><td>Remote-Desktop (4K / 60 FPS)</td><td>Verfügbar</td></tr><tr><td>Tastatur- und Mausweiterleitung</td><td>Verfügbar</td></tr><tr><td>Touch-Eingabe-Zuordnung</td><td>Verfügbar</td></tr><tr><td>Terminal-Sitzungen</td><td>Verfügbar</td></tr><tr><td>Datei-Browsing und Downloads</td><td>Verfügbar</td></tr><tr><td>Kamera-Streaming</td><td>Verfügbar</td></tr><tr><td>Bildschirmfreigabe mit Teammitgliedern</td><td>Geplant</td></tr><tr><td>Ansichts- und Vollkontroll-Berechtigungsmodi</td><td>Geplant</td></tr></tbody></table> <h2 id="so-lesen-sie-diese-seite">So lesen Sie diese Seite</h2> <p>„Verfügbar” bedeutet, dass die Funktion in den aktuellen Early-Access-Builds für mindestens eine Plattform enthalten ist; die Seite <a href="/de/docs/basics/permissions">Berechtigungen</a> führt auf, was jede Funktion auf der Workstation benötigt. Als „Geplant” markierte Funktionen stehen auf der Roadmap, sind aber noch nicht Teil der aktuellen Builds — erwarten Sie nicht, dass sie bereits funktionieren.</p> <p>Diese Seite wird im Verlauf des Early-Access-Programms aktualisiert. Die Liste der unterstützten Plattformen und Funktionen findet sich auch auf der Seite <a href="/de/docs/basics/getting-started">Erste Schritte</a>.</p>`,1);function qt(e){var t=Kt();n(14),i(e,t)}var Jt=r({default:()=>rn,metadata:()=>R}),R={title:`Dateiübertragung`,description:`Durchsuchen Sie Dateien auf Ihrer Workstation, zeigen Sie Vorschauen an und laden Sie Dateien herunter.`,section:`Basics`,order:30,published:!0,updated:`2026-08-16T00:00:00.000Z`,toc:[`Remote-Dateien durchsuchen`,`Dateien in der Vorschau ansehen`,`Dateien herunterladen`,`Dateien verwalten`,`Sicherheit beim Übertragen`]},{title:Yt,description:Xt,section:Zt,order:Qt,published:$t,updated:en,toc:tn}=R,nn=t(`<h2 id="remote-dateien-durchsuchen">Remote-Dateien durchsuchen</h2> <p>Die Dateiansicht gibt Ihnen ein Fenster in das Dateisystem der verbundenen Workstation. Sie können:</p> <ul><li>Ordner mit Breadcrumbs navigieren, wie in einem lokalen Dateimanager</li> <li>Häufige Orte (Home, Desktop, Downloads) über das Lesezeichen-Menü öffnen</li> <li>Zwischen Listen- und Rasteransicht wechseln</li> <li>Einträge nach Name, Art, Größe oder Änderungsdatum sortieren</li></ul> <p>Ordnerlisten werden als schlanke Metadaten gesendet, sodass sich das Öffnen eines Ordners auch bei langsameren Verbindungen sofort anfühlt. Vorschaubilder für Bilder und andere unterstützte Dateien laden nach und nach im Hintergrund.</p> <h2 id="dateien-in-der-vorschau-ansehen">Dateien in der Vorschau ansehen</h2> <p>Wählen Sie eine Datei aus und wählen Sie <strong>Vorschau</strong>, um ihren Inhalt zu sehen, ohne sie zuerst herunterzuladen. Vorschauen werden auf der Workstation erzeugt und über den Tunnel gesendet — große Dateien müssen also nicht erst auf Ihr Gerät übertragen werden, nur um einen Blick hineinzuwerfen.</p> <h2 id="dateien-herunterladen">Dateien herunterladen</h2> <p>So kopieren Sie eine Datei auf Ihr Gerät:</p> <ol><li>Öffnen Sie den Ordner mit der Datei.</li> <li>Wählen Sie die Datei aus (oder nutzen Sie die Mehrfachauswahl für mehrere Dateien).</li> <li>Wählen Sie <strong>Herunterladen</strong> im Kontextmenü.</li> <li>Wählen Sie ein Ziel auf Ihrem Gerät.</li></ol> <p>Downloads laufen über denselben Ende-zu-Ende-verschlüsselten QUIC-Tunnel wie der Rest Ihrer Sitzung.</p> <h2 id="dateien-verwalten">Dateien verwalten</h2> <p>Die Dateiansicht unterstützt außerdem grundlegende Dateiverwaltung auf der Workstation:</p> <ul><li><strong>Umbenennen</strong> — Dateien und Ordner direkt umbenennen</li> <li><strong>Löschen</strong> — Einträge entfernen, mit Bestätigungsschritt vor dem Löschen</li> <li><strong>Neuer Ordner</strong> — Verzeichnisse auf der Workstation anlegen</li> <li><strong>Info</strong> — Größe, Änderungsdatum, Berechtigungen und weitere Details anzeigen</li></ul> <h2 id="sicherheit-beim-übertragen">Sicherheit beim Übertragen</h2> <p>Dateilisten, Vorschauen und Downloads laufen vollständig innerhalb Ihres verschlüsselten Tunnels. Nichts, was mit Ihren Dateien zu tun hat, wird jemals im Klartext übertragen, und Relay-Server, die für das Fallback-Routing genutzt werden, leiten nur verschlüsselte Bytes weiter — sie können Ihre Daten nicht lesen.</p>`,1);function rn(e){var t=nn();n(28),i(e,t)}var an=r({default:()=>mn,metadata:()=>z}),z={title:`Erste Schritte`,description:`Richten Sie Wihaister ein und stellen Sie Ihre erste Verbindung her.`,section:`Basics`,order:10,published:!0,updated:`2026-08-16T00:00:00.000Z`,toc:[`Früher Zugang`,`Wihaister installieren`,`Erste Verbindung herstellen`,`Plattform-Verfügbarkeit`,`Systemanforderungen`]},{title:on,description:sn,section:cn,order:ln,published:un,updated:dn,toc:fn}=z,pn=t(`<h2 id="früher-zugang">Früher Zugang</h2> <p>Wihaister ist derzeit über das Early-Access-Programm erhältlich. Installationspakete werden an Early-Access-Mitglieder versendet — falls Sie noch keins erhalten haben, <a href="/">sichern Sie sich frühen Zugang</a>.</p> <h2 id="wihaister-installieren">Wihaister installieren</h2> <h3 id="windows">Windows</h3> <ol><li>Führen Sie den <code>.exe</code>-Installer aus und folgen Sie dem Einrichtungsassistenten.</li> <li>Wihaister startet automatisch nach der Installation.</li> <li>Ein System-Tray-Symbol erscheint, wenn der Tunnel-Dienst läuft.</li></ol> <h3 id="macos">macOS</h3> <ol><li>Öffnen Sie das <code>.dmg</code>-Image und ziehen Sie Wihaister in den Programme-Ordner.</li> <li>Starten Sie Wihaister aus dem Programme-Ordner.</li> <li>Erteilen Sie die Bildschirmaufnahme-Berechtigung (erforderlich für Remote-Desktop).</li></ol> <h2 id="erste-verbindung-herstellen">Erste Verbindung herstellen</h2> <ol><li>Öffnen Sie den Wihaister-Client auf beiden Geräten.</li> <li>Teilen Sie einen Verbindungscode vom Host-Gerät.</li> <li>Geben Sie den Code auf dem Client-Gerät ein.</li> <li>Die Verbindung wird automatisch hergestellt.</li></ol> <h2 id="plattform-verfügbarkeit">Plattform-Verfügbarkeit</h2> <ul><li><strong>Windows</strong> und <strong>macOS</strong> sind heute verfügbar.</li> <li><strong>Linux</strong>-Unterstützung ist geplant.</li> <li><strong>iOS</strong>- und <strong>Android</strong>-Clients sind in aktiver Entwicklung.</li></ul> <h2 id="systemanforderungen">Systemanforderungen</h2> <ul><li><strong>Windows</strong>: Windows 10 oder neuer</li> <li><strong>macOS</strong>: macOS 12 Monterey oder neuer</li></ul>`,1);function mn(e){var t=pn();n(24),i(e,t)}var hn=r({default:()=>wn,metadata:()=>B}),B={title:`Berechtigungen`,description:`Welche Berechtigungen Wihaister auf der Workstation benötigt und wie Sie sie erteilen.`,section:`Basics`,order:45,published:!0,updated:`2026-08-16T00:00:00.000Z`,toc:[`macOS`,`Windows`,`macOS-Berechtigungen erteilen`,`Häufige Fragen`]},{title:gn,description:_n,section:vn,order:yn,published:bn,updated:xn,toc:Sn}=B,Cn=t(`<h2 id="macos">macOS</h2> <p>Wenn Wihaister als Host auf macOS läuft, kann es diese Berechtigungen anfragen:</p> <table><thead><tr><th>Berechtigung</th><th>Wofür sie benötigt wird</th><th>Was ohne sie nicht funktioniert</th></tr></thead><tbody><tr><td>Bildschirmaufnahme</td><td>Erfassen des Bildschirms für den Remote-Desktop-Stream</td><td>Remote-Desktop zeigt einen schwarzen Bildschirm</td></tr><tr><td>Kamera</td><td>Streamen von Kameras an der Workstation</td><td>Das Kamerabild ist nicht verfügbar</td></tr><tr><td>Bedienungshilfen</td><td>Weiterleiten von Tastatur- und Mauseingaben</td><td>Eingaben erreichen Anwendungen nicht</td></tr></tbody></table> <p>Sie werden nur beim ersten Einsatz der jeweiligen Funktion um eine Berechtigung gebeten.</p> <h2 id="windows">Windows</h2> <p>Unter Windows läuft Wihaister als Dienst mit Tray-Symbol. Streaming und Eingabeweiterleitung benötigen keine besonderen Berechtigungen. Läuft der Tunnel-Dienst nicht, fehlt das Tray-Symbol — starten Sie Wihaister über das Startmenü.</p> <h2 id="macos-berechtigungen-erteilen">macOS-Berechtigungen erteilen</h2> <p>Berechtigungen können jederzeit erteilt oder widerrufen werden:</p> <ol><li>Öffnen Sie <strong>Systemeinstellungen → Datenschutz & Sicherheit</strong>.</li> <li>Wählen Sie die Kategorie (<strong>Bildschirmaufnahme</strong>, <strong>Kamera</strong> oder <strong>Bedienungshilfen</strong>).</li> <li>Aktivieren Sie Wihaister.</li> <li>Starten Sie den Wihaister-Dienst neu, damit die Änderung wirksam wird.</li></ol> <p>macOS fordert Sie möglicherweise auf, eine App neu zu starten, nachdem Sie ihre Bildschirmaufnahme-Berechtigung geändert haben.</p> <h2 id="häufige-fragen">Häufige Fragen</h2> <p><strong>Ich habe die Bildschirmaufnahme erteilt, aber der Bildschirm bleibt schwarz.</strong> Starten Sie den Wihaister-Dienst neu — macOS übernimmt die Änderung erst nach einem Neustart der App.</p> <p><strong>Eine Berechtigung fehlt in der Liste.</strong> Führen Sie Wihaister einmal aus — die App erscheint erst in einer Kategorie, nachdem sie die Berechtigung angefordert hat. Fehlt sie weiterhin, installieren Sie die App neu.</p> <p><strong>Beeinflussen Berechtigungen die Privatsphäre?</strong> Berechtigungen werden ausschließlich vom Betriebssystem auf der Workstation geprüft. Alles Erfasste läuft durch Ihren Ende-zu-Ende-verschlüsselten Tunnel; Wihaister speichert nichts.</p>`,1);function wn(e){var t=Cn();n(26),i(e,t)}var Tn=r({default:()=>Pn,metadata:()=>V}),V={title:`Remote-Desktop-Steuerung`,description:`Alles, was Sie tun können, sobald Sie den entfernten Bildschirm sehen.`,section:`Basics`,order:20,published:!0,updated:`2026-08-16T00:00:00.000Z`,toc:[`Monitor auswählen`,`Bildqualität`,`Tastatur und Maus`,`Touch-Steuerung`,`Sitzung beenden`]},{title:En,description:Dn,section:On,order:kn,published:An,updated:jn,toc:Mn}=V,Nn=t(`<h2 id="monitor-auswählen">Monitor auswählen</h2> <p>Beim Verbinden streamt Wihaister einen Monitor der Workstation. Hat die Workstation mehrere Bildschirme, können Sie im Client zwischen ihnen wechseln — jeweils ein Monitor zur Zeit. Die Liste der verfügbaren Monitore wird beim Sitzungsstart abgerufen; der Wechsel zu einem anderen Monitor geschieht ohne erneutes Verbinden.</p> <h2 id="bildqualität">Bildqualität</h2> <p>Wihaister unterstützt Streaming bis zu <strong>4K mit 60 FPS</strong>. Der Stream passt sich automatisch an Ihre Verbindung an: In einem schnellen Netz bleibt das Bild in voller Qualität, bei Engpässen wird die Qualität sanft reduziert, statt zu frieren oder die Sitzung abzubrechen. Sobald Bandbreite verfügbar wird, steigt die Qualität automatisch wieder an.</p> <h2 id="tastatur-und-maus">Tastatur und Maus</h2> <p>Ihre Tastatur und Maus werden in Echtzeit an die Workstation weitergeleitet:</p> <ul><li>Tippen, Tastenkürzel und Modifikatortasten verhalten sich, als säßen Sie direkt an der Maschine</li> <li>Klicks, Ziehen und Scrollen werden als Mauseingaben weitergeleitet</li> <li>Der Client übersetzt Ihre Gesten in die Ereignisse, die die Workstation erwartet</li></ul> <p>Keine Konfiguration nötig — die Eingabeweiterleitung ist aktiv, sobald die Sitzung startet.</p> <h2 id="touch-steuerung">Touch-Steuerung</h2> <p>Auf Geräten mit Touchscreen steuern Sie die Sitzung per Berührung. Tippen und Gesten werden auf Mausaktionen der Workstation abgebildet. Details finden Sie unter <a href="/de/docs/basics/touch-input">Touch-Eingabe</a>.</p> <h2 id="sitzung-beenden">Sitzung beenden</h2> <p>Schließen Sie die Remote-Desktop-Ansicht oder trennen Sie die Verbindung im Client, um die Sitzung zu beenden. Der Tunnel wird automatisch abgebaut.</p>`,1);function Pn(e){var t=Nn();n(22),i(e,t)}var Fn=r({default:()=>Wn,metadata:()=>H}),H={title:`Terminal-Sitzungen`,description:`Öffnen Sie eine interaktive Shell auf der entfernten Workstation.`,section:`Basics`,order:25,published:!0,updated:`2026-08-16T00:00:00.000Z`,toc:[`Was eine Terminal-Sitzung ist`,`Eine Sitzung öffnen`,`Mit Sitzungen arbeiten`,`Sicherheit`]},{title:In,description:Ln,section:Rn,order:zn,published:Bn,updated:Vn,toc:Hn}=H,Un=t(`<h2 id="was-eine-terminal-sitzung-ist">Was eine Terminal-Sitzung ist</h2> <p>Eine Terminal-Sitzung gibt Ihnen eine interaktive Shell auf der entfernten Workstation — dieselbe Art von Eingabeaufforderung, die Sie bekämen, wenn Sie ein Terminal auf der Maschine selbst öffnen würden. Ihre gewohnte Shell und Ihre Kommandozeilen-Werkzeuge sind verfügbar: Sie können Builds ausführen, Prozesse verwalten, Konfigurationsdateien bearbeiten und Probleme beheben, ohne den Wihaister-Client zu verlassen.</p> <p>Jede Sitzung läuft als eigener Shell-Prozess auf der Workstation, innerhalb desselben Ende-zu-Ende-verschlüsselten Tunnels wie der Rest Ihrer Sitzung.</p> <h2 id="eine-sitzung-öffnen">Eine Sitzung öffnen</h2> <ol><li>Verbinden Sie sich mit der Workstation.</li> <li>Öffnen Sie die Terminal-Ansicht im Client.</li> <li>Eine Shell startet auf der Workstation und erscheint im Client.</li></ol> <p>Auf Seiten der Workstation ist keine zusätzliche Einrichtung nötig — Sitzungen werden bei Bedarf über den Tunnel erstellt.</p> <h2 id="mit-sitzungen-arbeiten">Mit Sitzungen arbeiten</h2> <ul><li>Sie können <strong>mehrere Sitzungen</strong> öffnen und zwischen ihnen wechseln; jede behält ihr eigenes Arbeitsverzeichnis und ihre Prozessliste</li> <li>Sitzungen sind unabhängig — ein lange laufender Befehl in einer Sitzung blockiert die anderen nicht</li> <li>Tastatureingabe, Scrollen und Auswahl verhalten sich wie in einem lokalen Terminal</li></ul> <h2 id="sicherheit">Sicherheit</h2> <p>Alles, was Sie tippen, und jedes Byte der Ausgabe läuft durch Ihren verschlüsselten Tunnel. Terminal-Datenverkehr wird niemals im Klartext übertragen, und Relay-Server, die für das Fallback-Routing genutzt werden, können nur verschlüsselte Bytes weiterleiten.</p>`,1);function Wn(e){var t=Un();n(18),i(e,t)}var Gn=r({default:()=>er,metadata:()=>U}),U={title:`Touch-Eingabe`,description:`Steuern Sie Ihre Workstation mit Touch-Gesten auf berührungsempfindlichen Geräten.`,section:`Basics`,order:40,published:!0,updated:`2026-08-16T00:00:00.000Z`,toc:[`So funktioniert die Touch-Zuordnung`,`Häufige Gesten`,`Touch und Tastatur kombinieren`]},{title:Kn,description:qn,section:Jn,order:Yn,published:Xn,updated:Zn,toc:Qn}=U,$n=t(`<h2 id="so-funktioniert-die-touch-zuordnung">So funktioniert die Touch-Zuordnung</h2> <p>Wihaister bildet Touch-Gesten von Ihrem Client-Gerät auf Mausaktionen der Workstation ab. So steuern Sie den Remote-Desktop auf natürliche Weise über einen Touchscreen — etwa von einem Tablet oder einem Touch-Laptop aus.</p> <p>Touch-Eingaben laufen durch denselben verschlüsselten Tunnel wie Tastatur- und Mauseingaben und sind aktiv, sobald die Remote-Desktop-Sitzung läuft.</p> <h2 id="häufige-gesten">Häufige Gesten</h2> <ul><li><strong>Tippen</strong> — ein Mausklick an der getippten Position</li> <li><strong>Ziehen</strong> — gedrückt halten und bewegen, wird als Maus-Ziehen weitergeleitet (zum Auswählen von Text, Verschieben von Fenstern und Zeichnen)</li> <li><strong>Scrollen</strong> — Wischgesten senden Scroll-Ereignisse</li></ul> <p>Welche Gesten genau verfügbar sind, hängt von Ihrem Client ab. Die Touch-Bedienung ist darauf ausgelegt, mit der Bildschirmtastatur Ihres Geräts zusammenzuarbeiten.</p> <h2 id="touch-und-tastatur-kombinieren">Touch und Tastatur kombinieren</h2> <p>Zeigt Ihr Gerät eine Bildschirmtastatur an, werden ihre Tastenanschläge wie physische Tastatureingaben an die Workstation weitergeleitet. Sie können Textfelder und Terminals mit Touch bedienen und über die Bildschirmtastatur tippen.</p>`,1);function er(e){var t=$n();n(14),i(e,t)}var tr=r({default:()=>ur,metadata:()=>W}),W={title:`Problembehandlung`,description:`Häufige Verbindungs-, Berechtigungs- und Leistungsprobleme lösen.`,section:`Basics`,order:50,published:!0,updated:`2026-08-16T00:00:00.000Z`,toc:[`Der Bildschirm ist schwarz`,`Das Kamerabild fehlt`,`Probleme mit dem Verbindungscode`,`Die Verbindung ist langsam`,`Warum läuft meine Sitzung über ein Relay`,`Verbindungsabbrüche`,`Diagnosedaten sammeln`,`Immer noch festgefahren`]},{title:nr,description:rr,section:ir,order:ar,published:or,updated:sr,toc:cr}=W,lr=t(`<h2 id="der-bildschirm-ist-schwarz">Der Bildschirm ist schwarz</h2> <p>Ein schwarzer Remote-Desktop bedeutet fast immer eine fehlende Berechtigung auf dem Host (dem gesteuerten Rechner). Die vollständige Liste finden Sie unter <a href="/de/docs/basics/permissions">Berechtigungen</a>.</p> <p>Schnellcheckliste:</p> <ul><li><strong>macOS</strong>: Bildschirmaufnahme-Berechtigung erteilen und den Wihaister-Dienst neu starten</li> <li><strong>Windows</strong>: Prüfen, ob der Tunnel-Dienst läuft — sein Symbol sollte im System-Tray sichtbar sein</li> <li>Beide Rechner sind online und verbunden</li></ul> <h2 id="das-kamerabild-fehlt">Das Kamerabild fehlt</h2> <p>Kamera-Streaming erfordert Kamerazugriff auf der <strong>Workstation</strong>:</p> <ol><li>Öffnen Sie <strong>Systemeinstellungen → Datenschutz & Sicherheit → Kamera</strong> (macOS).</li> <li>Aktivieren Sie Wihaister und starten Sie den Dienst neu.</li></ol> <p>Stellen Sie außerdem sicher, dass keine andere Anwendung die Kamera exklusiv nutzt — die meisten Kameras können nur von einer Anwendung gleichzeitig geöffnet werden.</p> <h2 id="probleme-mit-dem-verbindungscode">Probleme mit dem Verbindungscode</h2> <p>Verbindungscodes sind <strong>einmalig verwendbar</strong> und <strong>48 Stunden</strong> ab dem Zeitpunkt ihrer Erstellung gültig.</p> <ul><li>Wird ein Code abgelehnt, erzeugen Sie auf dem Host einen neuen und versuchen Sie es erneut — der alte Code kann nicht wiederverwendet werden</li> <li>Geben Sie den Code exakt wie angezeigt ein, einschließlich der Bindestriche (Format: <code>XXXX-XXXX-XXXX</code>)</li> <li>Codes verfallen automatisch nach 48 Stunden, auch wenn sie nie verwendet wurden</li></ul> <h2 id="die-verbindung-ist-langsam">Die Verbindung ist langsam</h2> <p>Wihaister passt die Stream-Qualität automatisch an Ihre Netzwerkbedingungen an. Wenn das Bild träge wirkt:</p> <ul><li>Näher an den WLAN-Zugangspunkt gehen oder eine Kabelverbindung nutzen</li> <li>Bandbreitenhungrige Anwendungen auf beiden Rechnern schließen</li> <li>Bedenken Sie: Beide Endpunkte zählen — das langsamste Glied in der Kette begrenzt die gesamte Sitzung</li> <li>Sitzungen über das Relay-Fallback haben eine höhere Latenz als direkte Verbindungen</li></ul> <h2 id="warum-läuft-meine-sitzung-über-ein-relay">Warum läuft meine Sitzung über ein Relay</h2> <p>Wihaister versucht immer zuerst eine <strong>direkte Peer-to-Peer-Verbindung</strong> zwischen Ihren Geräten herzustellen und durchstößt dabei NATs und Firewalls automatisch. In manchen Netzwerkumgebungen lässt sich ein direkter Pfad schlicht nicht aufbauen — restriktive Firewalls oder Carrier-Grade-NAT sind häufige Ursachen.</p> <p>In diesem Fall fällt die Sitzung so lange auf einen Relay-Server zurück, wie es nötig ist. Ihr Datenverkehr bleibt <strong>Ende-zu-Ende-verschlüsselt</strong>: Das Relay leitet nur verschlüsselte Bytes weiter und kann Ihre Daten nicht lesen. Funktional verhalten sich Relay-Sitzungen wie direkte — sie können lediglich eine etwas höhere Latenz haben.</p> <p>Ob eine Sitzung direkt oder über Relay läuft, lässt sich innerhalb des Produkts nicht erkennen — die Verbindung verhält sich in beiden Fällen identisch.</p> <h2 id="verbindungsabbrüche">Verbindungsabbrüche</h2> <ul><li>Prüfen, ob beide Rechner online sind und Wihaister auf beiden läuft</li> <li>Der Client verbindet automatisch neu — kurz warten, bevor Sie manuell eingreifen</li> <li>Geben Sie den Verbindungscode erneut ein, wenn die Sitzung nicht fortgesetzt werden kann; Codes sind einmalig, teilen Sie also einen frischen Code vom Host</li> <li>Reagiert der Tunnel-Dienst nicht, starten Sie ihn auf dem Host neu und verbinden Sie erneut</li></ul> <h2 id="diagnosedaten-sammeln">Diagnosedaten sammeln</h2> <p>Wenn Sie Hilfe vom Team benötigen, beschleunigen ein paar Details die Fehlersuche:</p> <ul><li>Welche Plattformen beide Rechner nutzen (und ihre Betriebssystemversionen)</li> <li>Was Sie gerade taten, als das Problem auftrat</li> <li>Ob das Problem bei jeder Verbindung oder nur in bestimmten Netzwerken auftritt</li> <li>Der genaue Wortlaut jeder Fehlermeldung</li></ul> <p>Für fortgeschrittene Diagnosen kann der Desktop-Client mit ausführlichem Logging gestartet werden, indem Sie die Umgebungsvariable <code>RUST_LOG</code> vor dem Start in einem Terminal auf <code>debug</code> setzen.</p> <h2 id="immer-noch-festgefahren">Immer noch festgefahren</h2> <p>Wihaister befindet sich im Early Access. Wenn sich ein Problem mit den obigen Schritten nicht lösen lässt, wenden Sie sich über den Kanal aus Ihrer Early-Access-Einladung an uns — idealerweise mit den Diagnosedaten aus dem vorherigen Abschnitt.</p>`,1);function ur(e){var t=lr();n(50),i(e,t)}var dr=r({default:()=>br,metadata:()=>G}),G={title:`Strumieniowanie kamery`,description:`Używaj kamery podłączonej do stacji roboczej ze swojego urządzenia klienckiego.`,section:`Basics`,order:35,published:!0,updated:`2026-08-16T00:00:00.000Z`,toc:[`Do czego służy strumieniowanie kamery`,`Uruchamianie strumienia kamery`,`Uprawnienia`,`Jakość i wydajność`,`Prywatność`]},{title:fr,description:pr,section:mr,order:hr,published:gr,updated:_r,toc:vr}=G,yr=t(`<h2 id="do-czego-służy-strumieniowanie-kamery">Do czego służy strumieniowanie kamery</h2> <p>Strumieniowanie kamery przekazuje obraz z kamery podłączonej do Twojej stacji roboczej — na przykład kamery internetowej lub urządzenia przechwytującego — na Twoje urządzenie klienckie. Obraz z kamery jest przechwytywany na stacji roboczej, kompresowany i dostarczany przez Twój zaszyfrowany tunel.</p> <p>Przydaje się to do podglądania fizycznego miejsca, monitorowania stanowiska pracy lub korzystania z kamery stacji roboczej, do której Twoje urządzenie klienckie nie ma dostępu.</p> <h2 id="uruchamianie-strumienia-kamery">Uruchamianie strumienia kamery</h2> <ol><li>Połącz się ze stacją roboczą jak zwykle.</li> <li>Otwórz widok kamery w kliencie.</li> <li>Wybierz kamerę, której chcesz używać na stacji roboczej.</li></ol> <p>Strumień uruchamia się automatycznie. Zamknij widok kamery, aby zatrzymać strumień.</p> <h2 id="uprawnienia">Uprawnienia</h2> <p>W macOS Wihaister potrzebuje dostępu do kamery na <strong>stacji roboczej</strong>:</p> <ol><li>Otwórz <strong>Ustawienia systemowe → Prywatność i bezpieczeństwo → Kamera</strong>.</li> <li>Włącz Wihaister.</li> <li>Uruchom ponownie usługę Wihaister, jeśli kamera się nie pojawia.</li></ol> <p>W systemie Windows kamera jest dostępna, gdy usługa tunelowania działa w zasobniku systemowym.</p> <h2 id="jakość-i-wydajność">Jakość i wydajność</h2> <p>Klatki z kamery są kompresowane na stacji roboczej przed wysłaniem, więc strumień dostosowuje się do Twojego połączenia. Jeśli jakość obrazu spada, zwykle oznacza to przeciążenie połączenia — strumień wróci do normy automatycznie, gdy dostępna będzie większa przepustowość.</p> <h2 id="prywatność">Prywatność</h2> <p>Klatki z kamery wędrują przez ten sam szyfrowany od końca do końca tunel QUIC co cała reszta sesji. Klatki nigdy nie są przesyłane jawnym tekstem, a serwer przekaźnikowy używany do trasowania awaryjnego może przekazywać wyłącznie zaszyfrowane bajty — nie widzi obrazu z Twojej kamery.</p>`,1);function br(e){var t=yr();n(26),i(e,t)}var xr=r({default:()=>Ar,metadata:()=>K}),K={title:`Dostępność funkcji`,description:`Które platformy i funkcje są dostępne dzisiaj, w rozwoju lub w planach.`,section:`Basics`,order:60,published:!0,updated:`2026-08-16T00:00:00.000Z`,toc:[`Platformy`,`Funkcje`,`Jak czytać tę stronę`]},{title:Sr,description:Cr,section:wr,order:Tr,published:Er,updated:Dr,toc:Or}=K,kr=t(`<h2 id="platformy">Platformy</h2> <table><thead><tr><th>Platforma</th><th>Status</th></tr></thead><tbody><tr><td>Windows</td><td>Dostępna dzisiaj</td></tr><tr><td>macOS</td><td>Dostępna dzisiaj</td></tr><tr><td>Linux</td><td>W planach</td></tr><tr><td>iOS</td><td>W aktywnej fazie rozwoju</td></tr><tr><td>Android</td><td>W aktywnej fazie rozwoju</td></tr></tbody></table> <p>Możesz połączyć się ze stacją roboczą z dowolnego urządzenia z obsługiwanym klientem. Platformy oznaczone jako „w rozwoju” nie są jeszcze dystrybuowane z kompilacjami wczesnego dostępu.</p> <h2 id="funkcje">Funkcje</h2> <table><thead><tr><th>Funkcja</th><th>Status</th></tr></thead><tbody><tr><td>Zdalny pulpit (4K / 60 FPS)</td><td>Dostępna</td></tr><tr><td>Przekazywanie klawiatury i myszy</td><td>Dostępna</td></tr><tr><td>Mapowanie dotyku</td><td>Dostępna</td></tr><tr><td>Sesje terminala</td><td>Dostępna</td></tr><tr><td>Przeglądanie i pobieranie plików</td><td>Dostępna</td></tr><tr><td>Strumieniowanie kamery</td><td>Dostępna</td></tr><tr><td>Współdzielenie ekranu z zespołem</td><td>W planach</td></tr><tr><td>Tryby uprawnień tylko-do-odczytu i pełnej kontroli</td><td>W planach</td></tr></tbody></table> <h2 id="jak-czytać-tę-stronę">Jak czytać tę stronę</h2> <p>„Dostępna” oznacza, że funkcja znajduje się w bieżących kompilacjach wczesnego dostępu dla co najmniej jednej platformy; strona <a href="/pl/docs/basics/permissions">Uprawnienia</a> opisuje, czego każda funkcja potrzebuje na stacji roboczej. Funkcje oznaczone jako „W planach” są na mapie drogowej, ale nie są jeszcze częścią bieżących kompilacji — nie oczekuj, że już działają.</p> <p>Ta strona jest aktualizowana wraz z postępem programu wczesnego dostępu. Lista obsługiwanych platform i funkcji znajduje się również na stronie <a href="/pl/docs/basics/getting-started">Pierwsze Kroki</a>.</p>`,1);function Ar(e){var t=kr();n(14),i(e,t)}var jr=r({default:()=>Br,metadata:()=>q}),q={title:`Przesyłanie plików`,description:`Przeglądaj pliki na stacji roboczej, wyświetlaj podglądy i pobieraj pliki na swoje urządzenie.`,section:`Basics`,order:30,published:!0,updated:`2026-08-16T00:00:00.000Z`,toc:[`Przeglądanie zdalnych plików`,`Podgląd plików`,`Pobieranie plików`,`Zarządzanie plikami`,`Bezpieczeństwo transferu`]},{title:Mr,description:Nr,section:Pr,order:Fr,published:Ir,updated:Lr,toc:Rr}=q,zr=t(`<h2 id="przeglądanie-zdalnych-plików">Przeglądanie zdalnych plików</h2> <p>Widok Pliki daje Ci okno na system plików połączonej stacji roboczej. Możesz:</p> <ul><li>Nawigować po folderach za pomocą ścieżek nawigacyjnych, jak w lokalnym menedżerze plików</li> <li>Otwierać często używane lokalizacje (Katalog domowy, Pulpit, Pobrane) z menu zakładek</li> <li>Przełączać się między widokiem listy a siatki</li> <li>Sortować wpisy według nazwy, rodzaju, rozmiaru lub daty modyfikacji</li></ul> <p>Listy folderów są wysyłane jako lekkie metadane, więc otwieranie folderu działa natychmiast nawet na wolniejszych połączeniach. Miniatury obrazów i innych obsługiwanych plików ładują się stopniowo w tle.</p> <h2 id="podgląd-plików">Podgląd plików</h2> <p>Wybierz plik i wybierz <strong>Podgląd</strong>, aby zobaczyć jego zawartość bez wcześniejszego pobierania. Podglądy są generowane na stacji roboczej i wysyłane tunelem — duże pliki nie muszą trafiać na Twoje urządzenie tylko po to, żebyś mógł do nich zajrzeć.</p> <h2 id="pobieranie-plików">Pobieranie plików</h2> <p>Aby skopiować plik na swoje urządzenie:</p> <ol><li>Otwórz folder zawierający plik.</li> <li>Wybierz plik (lub użyj wyboru wielokrotnego dla kilku plików naraz).</li> <li>Wybierz <strong>Pobierz</strong> z menu kontekstowego.</li> <li>Wybierz miejsce docelowe na swoim urządzeniu.</li></ol> <p>Pobieranie odbywa się przez ten sam szyfrowany od końca do końca tunel QUIC co reszta sesji.</p> <h2 id="zarządzanie-plikami">Zarządzanie plikami</h2> <p>Widok Pliki obsługuje także podstawowe zarządzanie plikami na stacji roboczej:</p> <ul><li><strong>Zmień nazwę</strong> — zmiana nazwy plików i folderów w miejscu</li> <li><strong>Usuń</strong> — usuwanie wpisów z potwierdzeniem przed usunięciem</li> <li><strong>Nowy folder</strong> — tworzenie katalogów na stacji roboczej</li> <li><strong>Informacje</strong> — rozmiar, data modyfikacji, uprawnienia i inne szczegóły</li></ul> <h2 id="bezpieczeństwo-transferu">Bezpieczeństwo transferu</h2> <p>Listy plików, podglądy i pobieranie odbywają się w całości wewnątrz Twojego zaszyfrowanego tunelu. Żadne dane związane z Twoimi plikami nie są przesyłane jawnym tekstem, a serwery przekaźnikowe używane do trasowania awaryjnego przekazują wyłącznie zaszyfrowane bajty — nie mogą odczytać Twoich danych.</p>`,1);function Br(e){var t=zr();n(28),i(e,t)}var Vr=r({default:()=>Xr,metadata:()=>J}),J={title:`Pierwsze Kroki`,description:`Skonfiguruj Wihaister i wykonaj pierwsze połączenie.`,section:`Basics`,order:10,published:!0,updated:`2026-08-16T00:00:00.000Z`,toc:[`Wczesny dostęp`,`Instalacja Wihaister`,`Pierwsze połączenie`,`Dostępność platform`,`Wymagania systemowe`]},{title:Hr,description:Ur,section:Wr,order:Gr,published:Kr,updated:qr,toc:Jr}=J,Yr=t(`<h2 id="wczesny-dostęp">Wczesny dostęp</h2> <p>Wihaister jest obecnie dostępny w ramach programu wczesnego dostępu. Instalatory są wysyłane do członków programu — jeśli jeszcze ich nie otrzymałeś, <a href="/">uzyskaj wczesny dostęp</a>.</p> <h2 id="instalacja-wihaister">Instalacja Wihaister</h2> <h3 id="windows">Windows</h3> <ol><li>Uruchom instalator <code>.exe</code> i postępuj zgodnie z kreatorem konfiguracji.</li> <li>Wihaister uruchamia się automatycznie po instalacji.</li> <li>Ikona w zasobniku systemowym pojawia się, gdy usługa tunelowania jest aktywna.</li></ol> <h3 id="macos">macOS</h3> <ol><li>Otwórz obraz <code>.dmg</code> i przeciągnij Wihaister do folderu Aplikacje.</li> <li>Uruchom Wihaister z folderu Aplikacje.</li> <li>Przyznaj uprawnienia do nagrywania ekranu (wymagane dla zdalnego pulpitu).</li></ol> <h2 id="pierwsze-połączenie">Pierwsze połączenie</h2> <ol><li>Otwórz klienta Wihaister na obu urządzeniach.</li> <li>Udostępnij kod połączenia z urządzenia hosta.</li> <li>Wprowadź kod na urządzeniu klienckim.</li> <li>Połączenie zostanie automatycznie nawiązane.</li></ol> <h2 id="dostępność-platform">Dostępność platform</h2> <ul><li><strong>Windows</strong> i <strong>macOS</strong> są dostępne już dziś.</li> <li>Wsparcie dla <strong>Linuksa</strong> jest w planach.</li> <li>Klienci na <strong>iOS</strong> i <strong>Androida</strong> są w aktywnej fazie rozwoju.</li></ul> <h2 id="wymagania-systemowe">Wymagania systemowe</h2> <ul><li><strong>Windows</strong>: Windows 10 lub nowszy</li> <li><strong>macOS</strong>: macOS 12 Monterey lub nowszy</li></ul>`,1);function Xr(e){var t=Yr();n(24),i(e,t)}var Zr=r({default:()=>oi,metadata:()=>Y}),Y={title:`Uprawnienia`,description:`Jakich uprawnień Wihaister potrzebuje na stacji roboczej i jak je przyznać.`,section:`Basics`,order:45,published:!0,updated:`2026-08-16T00:00:00.000Z`,toc:[`macOS`,`Windows`,`Przyznawanie uprawnień w macOS`,`Częste pytania`]},{title:Qr,description:$r,section:ei,order:ti,published:ni,updated:ri,toc:ii}=Y,ai=t(`<h2 id="macos">macOS</h2> <p>Gdy Wihaister działa jako host w macOS, może poprosić o te uprawnienia:</p> <table><thead><tr><th>Uprawnienie</th><th>Po co jest potrzebne</th><th>Co nie działa bez niego</th></tr></thead><tbody><tr><td>Nagrywanie ekranu</td><td>Przechwytywanie ekranu do strumieniowania zdalnego pulpitu</td><td>Zdalny pulpit pokazuje czarny ekran</td></tr><tr><td>Kamera</td><td>Strumieniowanie kamer podłączonych do stacji roboczej</td><td>Obraz z kamery jest niedostępny</td></tr><tr><td>Dostępność</td><td>Przekazywanie wejścia z klawiatury i myszy</td><td>Wejście nie dociera do aplikacji</td></tr></tbody></table> <p>O uprawnienie jesteś proszony dopiero przy pierwszym użyciu danej funkcji.</p> <h2 id="windows">Windows</h2> <p>W systemie Windows Wihaister działa jako usługa z ikoną w zasobniku. Strumieniowanie i przekazywanie wejścia nie wymagają specjalnych uprawnień. Jeśli usługa tunelowania nie działa, brakuje ikony w zasobniku — uruchom Wihaister z menu Start.</p> <h2 id="przyznawanie-uprawnień-w-macos">Przyznawanie uprawnień w macOS</h2> <p>Uprawnienia można przyznać lub cofnąć w dowolnym momencie:</p> <ol><li>Otwórz <strong>Ustawienia systemowe → Prywatność i bezpieczeństwo</strong>.</li> <li>Wybierz kategorię (<strong>Nagrywanie ekranu</strong>, <strong>Kamera</strong> lub <strong>Dostępność</strong>).</li> <li>Włącz Wihaister.</li> <li>Uruchom ponownie usługę Wihaister, aby zmiana zaczęła obowiązywać.</li></ol> <p>macOS może poprosić o ponowne uruchomienie aplikacji po zmianie jej uprawnienia do nagrywania ekranu.</p> <h2 id="częste-pytania">Częste pytania</h2> <p><strong>Przyznałem nagrywanie ekranu, ale ekran nadal jest czarny.</strong> Uruchom ponownie usługę Wihaister — macOS uwzględnia zmianę dopiero po restarcie aplikacji.</p> <p><strong>Brakuje uprawnienia na liście.</strong> Uruchom Wihaister raz — aplikacja pojawia się w kategorii dopiero po tym, jak poprosi o to uprawnienie. Jeśli nadal jej nie ma, zainstaluj aplikację ponownie.</p> <p><strong>Czy uprawnienia wpływają na prywatność?</strong> Uprawnienia są sprawdzane wyłącznie przez system operacyjny na stacji roboczej. Wszystko, co jest przechwytywane, trafia przez Twój szyfrowany od końca do końca tunel; Wihaister niczego nie przechowuje.</p>`,1);function oi(e){var t=ai();n(26),i(e,t)}var si=r({default:()=>gi,metadata:()=>X}),X={title:`Sterowanie pulpitem zdalnym`,description:`Wszystko, co możesz zrobić, gdy widzisz już zdalny ekran.`,section:`Basics`,order:20,published:!0,updated:`2026-08-16T00:00:00.000Z`,toc:[`Wybór monitora`,`Jakość obrazu`,`Klawiatura i mysz`,`Sterowanie dotykiem`,`Kończenie sesji`]},{title:ci,description:li,section:ui,order:di,published:fi,updated:pi,toc:mi}=X,hi=t(`<h2 id="wybór-monitora">Wybór monitora</h2> <p>Po połączeniu Wihaister przesyła obraz monitora ze stacji roboczej. Jeśli stacja ma kilka ekranów, możesz przełączać się między nimi z klienta — jeden monitor naraz. Lista dostępnych monitorów jest pobierana przy starcie sesji, a wybór innego monitora przełącza strumień bez ponownego łączenia.</p> <h2 id="jakość-obrazu">Jakość obrazu</h2> <p>Wihaister obsługuje strumieniowanie do <strong>4K przy 60 FPS</strong>. Strumień automatycznie dostosowuje się do Twojego połączenia: w szybkiej sieci obraz pozostaje w pełnej jakości, a przy przeciążeniu jakość płynnie spada, zamiast zamrażać lub zrywać sesję. Gdy przepustowość wraca, jakość automatycznie wraca do poprzedniego poziomu.</p> <h2 id="klawiatura-i-mysz">Klawiatura i mysz</h2> <p>Klawiatura i mysz są przekazywane do stacji roboczej w czasie rzeczywistym:</p> <ul><li>Pisanie, skróty klawiszowe i klawisze modyfikujące działają tak, jakbyś siedział przy maszynie</li> <li>Kliknięcia, przeciąganie i przewijanie są przekazywane jako wejście myszy</li> <li>Klient tłumaczy Twoje gesty na zdarzenia, których oczekuje stacja robocza</li></ul> <p>Żadna konfiguracja nie jest wymagana — przekazywanie wejścia jest aktywne od momentu startu sesji.</p> <h2 id="sterowanie-dotykiem">Sterowanie dotykiem</h2> <p>Na urządzeniach z ekranem dotykowym możesz sterować sesją dotykiem. Stuknięcia i gesty są mapowane na działania myszy na stacji roboczej. Szczegóły znajdziesz na stronie <a href="/pl/docs/basics/touch-input">Obsługa dotyku</a>.</p> <h2 id="kończenie-sesji">Kończenie sesji</h2> <p>Zamknij widok zdalnego pulpitu lub rozłącz się w kliencie, aby zakończyć sesję. Tunel zostaje automatycznie zamknięty.</p>`,1);function gi(e){var t=hi();n(22),i(e,t)}var _i=r({default:()=>Ei,metadata:()=>Z}),Z={title:`Sesje terminala`,description:`Otwórz interaktywną powłokę na zdalnej stacji roboczej.`,section:`Basics`,order:25,published:!0,updated:`2026-08-16T00:00:00.000Z`,toc:[`Czym jest sesja terminala`,`Otwieranie sesji`,`Praca z sesjami`,`Bezpieczeństwo`]},{title:vi,description:yi,section:bi,order:xi,published:Si,updated:Ci,toc:wi}=Z,Ti=t(`<h2 id="czym-jest-sesja-terminala">Czym jest sesja terminala</h2> <p>Sesja terminala daje Ci interaktywną powłokę na zdalnej stacji roboczej — ten sam rodzaj wiersza poleceń, który zobaczysz, otwierając terminal na samej maszynie. Twoja zwykła powłoka i narzędzia wiersza poleceń są dostępne: możesz uruchamiać kompilacje, zarządzać procesami, edytować pliki konfiguracyjne i rozwiązywać problemy bez opuszczania klienta Wihaister.</p> <p>Każda sesja działa jako osobny proces powłoki na stacji roboczej, wewnątrz tego samego szyfrowanego od końca do końca tunelu co reszta Twojej sesji.</p> <h2 id="otwieranie-sesji">Otwieranie sesji</h2> <ol><li>Połącz się ze stacją roboczą.</li> <li>Otwórz widok terminala w kliencie.</li> <li>Powłoka uruchomi się na stacji roboczej i pojawi się w kliencie.</li></ol> <p>Po stronie stacji roboczej żadna dodatkowa konfiguracja nie jest potrzebna — sesje są tworzone na żądanie przez tunel.</p> <h2 id="praca-z-sesjami">Praca z sesjami</h2> <ul><li>Możesz otwierać <strong>wiele sesji</strong> i przełączać się między nimi; każda zachowuje własny katalog roboczy i listę procesów</li> <li>Sesje są niezależne — długo działające polecenie w jednej sesji nie blokuje pozostałych</li> <li>Wprowadzanie z klawiatury, przewijanie i zaznaczanie działają jak w lokalnym terminalu</li></ul> <h2 id="bezpieczeństwo">Bezpieczeństwo</h2> <p>Wszystko, co wpisujesz, i każdy bajt wyjścia wędruje przez Twój zaszyfrowany tunel. Ruch terminala nigdy nie jest przesyłany jawnym tekstem, a serwery przekaźnikowe używane do trasowania awaryjnego mogą przekazywać wyłącznie zaszyfrowane bajty.</p>`,1);function Ei(e){var t=Ti();n(18),i(e,t)}var Di=r({default:()=>Ii,metadata:()=>Q}),Q={title:`Obsługa dotyku`,description:`Steruj stacją roboczą gestami dotykowymi na urządzeniach z ekranem dotykowym.`,section:`Basics`,order:40,published:!0,updated:`2026-08-16T00:00:00.000Z`,toc:[`Jak działa mapowanie dotyku`,`Typowe gesty`,`Łączenie dotyku z klawiaturą`]},{title:Oi,description:ki,section:Ai,order:ji,published:Mi,updated:Ni,toc:Pi}=Q,Fi=t(`<h2 id="jak-działa-mapowanie-dotyku">Jak działa mapowanie dotyku</h2> <p>Wihaister mapuje gesty dotykowe z Twojego urządzenia klienckiego na działania myszy na stacji roboczej. Dzięki temu możesz naturalnie sterować zdalnym pulpitem z ekranu dotykowego — na przykład z tabletu lub dotykowego laptopa.</p> <p>Wejście dotykowe wędruje przez ten sam zaszyfrowany tunel co wejście z klawiatury i myszy i jest aktywne, gdy tylko działa sesja zdalnego pulpitu.</p> <h2 id="typowe-gesty">Typowe gesty</h2> <ul><li><strong>Stuknięcie</strong> — kliknięcie myszy w miejscu dotknięcia</li> <li><strong>Przeciągnięcie</strong> — przytrzymanie i ruch, przekazywane jako przeciąganie myszy (do zaznaczania tekstu, przesuwania okien i rysowania)</li> <li><strong>Przewijanie</strong> — gesty przewijania wysyłają zdarzenia przewijania</li></ul> <p>Dokładny zestaw dostępnych gestów zależy od Twojego klienta. Obsługa dotyku jest zaprojektowana tak, aby współpracować z klawiaturą ekranową urządzenia.</p> <h2 id="łączenie-dotyku-z-klawiaturą">Łączenie dotyku z klawiaturą</h2> <p>Gdy na Twoim urządzeniu wyświetla się klawiatura ekranowa, jej naciśnięcia klawiszy są przekazywane do stacji roboczej tak samo jak wejście z fizycznej klawiatury. Możesz pisać w polach tekstowych i terminalach, używając dotyku do nawigacji i klawiatury ekranowej do tekstu.</p>`,1);function Ii(e){var t=Fi();n(14),i(e,t)}var Li=r({default:()=>Ki,metadata:()=>$}),$={title:`Rozwiązywanie problemów`,description:`Napraw typowe problemy z połączeniem, uprawnieniami i wydajnością.`,section:`Basics`,order:50,published:!0,updated:`2026-08-16T00:00:00.000Z`,toc:[`Czarny ekran`,`Brak obrazu z kamery`,`Problemy z kodem połączenia`,`Wolne połączenie`,`Dlaczego moja sesja korzysta z przekaźnika`,`Zrywanie połączenia`,`Zbieranie danych diagnostycznych`,`Nadal nie działa`]},{title:Ri,description:zi,section:Bi,order:Vi,published:Hi,updated:Ui,toc:Wi}=$,Gi=t(`<h2 id="czarny-ekran">Czarny ekran</h2> <p>Czarny zdalny pulpit niemal zawsze oznacza brakujące uprawnienie na hoście (kontrolowanej maszynie). Pełną listę znajdziesz na stronie <a href="/pl/docs/basics/permissions">Uprawnienia</a>.</p> <p>Szybka lista kontrolna:</p> <ul><li><strong>macOS</strong>: przyznaj uprawnienie do nagrywania ekranu i uruchom ponownie usługę Wihaister</li> <li><strong>Windows</strong>: sprawdź, czy usługa tunelowania działa — jej ikona powinna być widoczna w zasobniku systemowym</li> <li>Oba komputery online i połączone</li></ul> <h2 id="brak-obrazu-z-kamery">Brak obrazu z kamery</h2> <p>Strumieniowanie kamery wymaga dostępu do kamery na <strong>stacji roboczej</strong>:</p> <ol><li>Otwórz <strong>Ustawienia systemowe → Prywatność i bezpieczeństwo → Kamera</strong> (macOS).</li> <li>Włącz Wihaister i uruchom usługę ponownie.</li></ol> <p>Upewnij się też, że żadna inna aplikacja nie używa kamery wyłącznie — większość kamer może być otwarta tylko przez jedną aplikację naraz.</p> <h2 id="problemy-z-kodem-połączenia">Problemy z kodem połączenia</h2> <p>Kody połączenia są <strong>jednorazowe</strong> i ważne <strong>48 godzin</strong> od momentu wygenerowania.</p> <ul><li>Jeśli kod zostanie odrzucony, wygeneruj nowy na hoście i spróbuj ponownie — stary kod nie może zostać użyty ponownie</li> <li>Wpisz kod dokładnie tak, jak jest wyświetlany, razem z myślnikami (format: <code>XXXX-XXXX-XXXX</code>)</li> <li>Kody wygasają automatycznie po 48 godzinach, nawet jeśli nigdy nie zostały użyte</li></ul> <h2 id="wolne-połączenie">Wolne połączenie</h2> <p>Wihaister automatycznie dostosowuje jakość obrazu do warunków sieciowych. Jeśli obraz działa ospale:</p> <ul><li>Zbliż się do punktu dostępowego Wi-Fi lub użyj połączenia przewodowego</li> <li>Zamknij aplikacje obciążające łącze na obu komputerach</li> <li>Pamiętaj, że liczą się oba końce: najwolniejszy odcinek trasy ogranicza całą sesję</li> <li>Sesje korzystające z przekaźnika awaryjnego mają wyższe opóźnienia niż połączenia bezpośrednie</li></ul> <h2 id="dlaczego-moja-sesja-korzysta-z-przekaźnika">Dlaczego moja sesja korzysta z przekaźnika</h2> <p>Wihaister zawsze najpierw próbuje zestawić <strong>bezpośrednie połączenie peer-to-peer</strong> między Twoimi urządzeniami, automatycznie przebijając się przez NAT-y i zapory sieciowe. W niektórych środowiskach sieciowych bezpośrednia ścieżka po prostu nie może zostać ustanowiona — restrykcyjne zapory lub NAT operatorski to częste przyczyny.</p> <p>W takim przypadku sesja korzysta z serwera przekaźnikowego tak długo, jak to konieczne. Twój ruch jest nadal <strong>szyfrowany od końca do końca</strong>: przekaźnik przekazuje wyłącznie zaszyfrowane bajty i nie może odczytać Twoich danych. Funkcjonalnie sesje przez przekaźnik zachowują się tak samo jak bezpośrednie — mogą mieć jedynie nieco wyższe opóźnienia.</p> <p>Nie da się sprawdzić wewnątrz produktu, czy sesja jest bezpośrednia czy przez przekaźnik — połączenie zachowuje się identycznie w obu przypadkach.</p> <h2 id="zrywanie-połączenia">Zrywanie połączenia</h2> <ul><li>Sprawdź, czy oba komputery są online i czy Wihaister działa na obu</li> <li>Klient łączy się ponownie automatycznie — poczekaj chwilę, zanim spróbujesz ręcznie</li> <li>Wpisz kod połączenia ponownie, jeśli sesji nie można wznowić; kody są jednorazowe, więc wyślij świeży kod z hosta</li> <li>Jeśli usługa tunelowania nie odpowiada, uruchom ją ponownie na hoście i połącz się ponownie</li></ul> <h2 id="zbieranie-danych-diagnostycznych">Zbieranie danych diagnostycznych</h2> <p>Jeśli potrzebujesz pomocy zespołu, kilka szczegółów przyspieszy diagnozę:</p> <ul><li>Jakie platformy działają na obu komputerach (i wersje systemów)</li> <li>Co robiłeś, gdy pojawił się problem</li> <li>Czy problem występuje przy każdym połączeniu, czy tylko w określonych sieciach</li> <li>Dokładna treść każdego komunikatu o błędzie</li></ul> <p>Do zaawansowanej diagnostyki klienta desktopowego można uruchomić z pełnym logowaniem, ustawiając zmienną środowiskową <code>RUST_LOG</code> na <code>debug</code> przed uruchomieniem w terminalu.</p> <h2 id="nadal-nie-działa">Nadal nie działa</h2> <p>Wihaister jest we wczesnym dostępie. Jeśli powyższe kroki nie rozwiążą problemu, skontaktuj się z nami przez kanał podany w zaproszeniu do wczesnego dostępu — najlepiej wraz z danymi diagnostycznymi z poprzedniej sekcji.</p>`,1);function Ki(e){var t=Gi();n(50),i(e,t)}export{b as C,fe as D,xe as E,a as O,w as S,f as T,Rt as _,Zr as a,M as b,xr as c,Gn as d,Fn as f,Jt as g,an as h,si as i,dr as l,hn as m,Di as n,Vr as o,Tn as p,_i as r,jr as s,Li as t,tr as u,Ot as v,g as w,O as x,vt as y};